 public static string DescribeContentDiagnostic(string raw){var r=Json().Deserialize<Dictionary<string,object>>(raw);if((S(r,"schema")!="reveng-task-content-diagnostic-v1"&&S(r,"schema")!="reveng-task-content-diagnostic-v2")||!Object.Equals(V(r,"automatic_admission"),false)||!Object.Equals(V(r,"semantic_PASS"),false)||!Object.Equals(V(r,"research_imported"),false))throw new InvalidDataException("Unsafe diagnostic policy; no acceptance performed");string state=S(r,"content_status");if(state!="FAIL_TASK_REVIEW"&&state!="NEEDS_TASK_REVIEW")throw new InvalidDataException("Diagnostic cannot approve content");var b=new StringBuilder("READ-ONLY DIAGNOSTIC; NOT IMPORTED; CONTENT NOT APPROVED\r\n");b.AppendLine("Schema/citations: "+S(r,"schema_citation_status")+" | Content: "+state);b.AppendLine(S(r,"schema_citation_meaning"));b.AppendLine("Task review: "+S(r,"task_review_provenance"));b.AppendLine("Raw SHA256: "+S(r,"raw_response_sha256"));b.AppendLine("FOUND / MISSING / PARTIAL / DISTORTED (task review):");foreach(var f in A(V(r,"facts")))b.AppendLine(S(f,"fact_id")+" | "+S(f,"task_review_status")+" | "+S(f,"expected")+"\r\n"+S(f,"task_review_note"));b.AppendLine("WHOLE COPYING / MODALITY (mechanical warnings, not a semantic judge):");foreach(var f in A(V(r,"findings")))b.AppendLine(S(f,"kind")+" annotation="+S(f,"annotation_index")+" | "+S(f,"explanation")+"\r\nQuote cues: "+J(V(f,"quote_cues"))+"\r\n"+S(f,"quote")+"\r\nReading: "+S(f,"reading"));foreach(var a in A(V(r,"annotations")))b.AppendLine("Annotation "+S(a,"index")+" "+S(a,"ref")+"\r\nExact quote: "+S(a,"quote")+"\r\nUnverified reading: "+S(a,"reading"));if(S(r,"schema")=="reveng-task-content-diagnostic-v2"){var o=D(V(r,"obligations"));if(S(o,"schema")!="reveng-source-span-obligation-view-v1"||!Object.Equals(V(o,"semantic_PASS"),false)||!Object.Equals(V(o,"automatic_admission"),false))throw new InvalidDataException("Unsafe obligation presentation");b.AppendLine("SOURCE SPAN OBLIGATIONS: "+S(o,"revision_status"));